(7510941, 1198842, 94815, '<td valign="top">Love the wall and Brice Marden-ish color and austerity. Haven''t quite decided about the tulips but for now they seem an intrusion of nature pulling back to reality. Or maybe that''s a good thing.</td>', 'Love the wall and Brice Marden-ish color and austerity. Haven''t quite decided about the tulips but for now they seem an intrusion of nature pulling back to reality. Or maybe that''s a good thing.', '2017-04-28 00:16:52.000000', NULL, 1),
(7510942, 1198814, 94815, '<td valign="top">Great grumpy old flower. A rose, really?</td>', 'Great grumpy old flower. A rose, really?', '2017-04-28 00:21:03.000000', NULL, 1),
(7510943, 1198610, 94815, '<td valign="top">The question is: how long did it take to clear out the cigarette butts and other debris? The result is incredibly pristine and beautifully shot.</td>', 'The question is: how long did it take to clear out the cigarette butts and other debris? The result is incredibly pristine and beautifully shot.', '2017-04-28 00:25:03.000000', NULL, 1),
(7510944, 1198395, 94815, '<td valign="top">Yes. Stuff happening here even is very slowly. Time encapsulated.</td>', 'Yes. Stuff happening here even is very slowly. Time encapsulated.', '2017-04-28 00:25:49.000000', NULL, 1),
(7510945, 1198800, 94815, '<td valign="top">These old things always seem to be communing with nature; maybe because that''s where they are usually found. Anyway good find.</td>', 'These old things always seem to be communing with nature; maybe because that''s where they are usually found. Anyway good find.', '2017-04-28 00:27:53.000000', NULL, 1),
(7510946, 1198422, 94815, '<td valign="top">Beautifully shot and almost painterly rendering. I think it is stronger or even much stronger without the bird.</td>', 'Beautifully shot and almost painterly rendering. I think it is stronger or even much stronger without the bird.', '2017-04-28 00:30:16.000000', NULL, 1),
(7510947, 1198857, 94815, '<td valign="top">What strikes me is the near Renaissance-quality rendering of the clouds and sea and how transcendental is all seems.</td>', 'What strikes me is the near Renaissance-quality rendering of the clouds and sea and how transcendental is all seems.', '2017-04-28 00:32:32.000000', NULL, 1),
(7510948, 1198851, 94815, '<td valign="top">Strength and earthiness are obvious but the there is also unexpected intimacy that pops out of these beautiful black &amp; white tones.</td>', 'Strength and earthiness are obvious but the there is also unexpected intimacy that pops out of these beautiful black & white tones.', '2017-04-28 00:35:21.000000', NULL, 1),
